xql_query:
// ============================================================
// Rule: SLP_Airflow S3 DAG Failure Detected
// Vendor: Airflow
// Objective:
// Detect activity associated with SLP_Airflow S3 DAG Failure Detected.
// Severity: SEV_040_HIGH
// Category: OTHER
// ============================================================
// SANITIZED: Environment-specific values replaced with generic placeholders.
// MITRE ATT&CK:
// Tactic: TA0040 - Impact
// Technique: T1499.002 - Endpoint Denial of Service: Service Exhaustion Flood

// Define a consulta como case insensitive.
// Isso evita diferença entre "ERROR", "Error" e "error", por exemplo.
config case_sensitive = false

// Dataset bruto onde os logs do Airflow via S3 estão sendo armazenados.
| dataset = airflows3_airflows3_raw 

// Filtra somente eventos do coletor/produto <AIRFLOW_INTEGRATION_NAME>
// e mensagens do tipo DATA_MESSAGE, que contêm os logs reais do Airflow.
| filter _vendor = "<AIRFLOW_INTEGRATION_NAME>"
    and _product = "<AIRFLOW_INTEGRATION_NAME>"
    and messageType = "DATA_MESSAGE"

// Converte o campo logEvents para string JSON e extrai o array de eventos.
// O logEvents contém múltiplos eventos dentro de um único registro.
| alter event_array = json_extract_array(to_json_string(logEvents), "$")

// Expande o array para transformar cada item do logEvents em uma linha individual.
// O limite de 500 evita expansão excessiva em registros muito grandes.
| arrayexpand event_array limit 500

// Converte cada item expandido do array para string JSON,
// permitindo extrair os campos internos com json_extract_scalar.
| alter event_obj = to_json_string(event_array)

// Extrai os campos principais do evento bruto:
// id do evento, timestamp original e o campo message.
| alter event_id = json_extract_scalar(event_obj, "$.id")
| alter event_timestamp = json_extract_scalar(event_obj, "$.timestamp")
| alter message_json = json_extract_scalar(event_obj, "$.message")

// O campo message também é um JSON em formato string.
// Aqui são extraídos os campos internos do log do Airflow:
// logger, event e level.
| alter airflow_logger = json_extract_scalar(message_json, "$.logger")
| alter airflow_event = json_extract_scalar(message_json, "$.event")
| alter airflow_level = json_extract_scalar(message_json, "$.level")

// Extrai informações operacionais do Airflow a partir do campo logStream.
// Normalmente o logStream contém o caminho com dag_id, run_id, task_id e attempt.
| alter dag_id = arrayindex(regextract(logStream, "dag_id=([^/]+)"), 0)
| alter run_id = arrayindex(regextract(logStream, "run_id=([^/]+)"), 0)
| alter task_id = arrayindex(regextract(logStream, "task_id=([^/]+)"), 0)
| alter attempt = arrayindex(regextract(logStream, "attempt=([0-9]+)"), 0)

// Mantém somente os campos relevantes para análise e investigação do alerta.
| fields _time, dag_id, run_id, task_id, attempt, event_id, event_timestamp, airflow_logger, airflow_level, airflow_event

// Filtra somente eventos classificados como erro.
// Exclui erro específico de envio de e-mail via SES,
// pois esse comportamento pode ser tratado como ruído operacional
// ou falha não crítica para a execução principal do DAG.


| filter (`dag_id` != """<INTERNAL_DAG_ID_1>""") 
| filter (`dag_id` != """<INTERNAL_DAG_ID_2>""") 
| filter (`airflow_level` = """error""") 
| filter (`airflow_event` != """❌ Erro ao enviar e-mail de resumo via SES: An error occurred (MessageRejected) when calling the SendRawEmail operation: Email address is not verified. The following identities failed the check in region US-EAST-1: <USER_EMAIL_1>, <USER_EMAIL_2>, <USER_EMAIL_3>""")
